// Lightweight Local QR Code Generator (No External CDN / Tracking Prevention Free)
// Supports Byte mode QR Code Versions 1-10 (Error Correction Level L) + Online Image Fallback
(function(global) {
  // GF(256) math for Reed-Solomon
  const EXP = new Uint8Array(512);
  const LOG = new Uint8Array(256);
  let x = 1;
  for (let i = 0; i < 255; i++) {
    EXP[i] = x;
    LOG[x] = i;
    x <<= 1;
    if (x & 0x100) x ^= 0x11d;
  }
  for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255];

  function gfMul(a, b) {
    return (a === 0 || b === 0) ? 0 : EXP[LOG[a] + LOG[b]];
  }

  function rsGeneratorPoly(degree) {
    let poly = new Uint8Array([1]);
    for (let i = 0; i < degree; i++) {
      const next = new Uint8Array(poly.length + 1);
      const root = EXP[i];
      for (let j = 0; j < poly.length; j++) {
        next[j] ^= poly[j];
        next[j + 1] ^= gfMul(poly[j], root);
      }
      poly = next;
    }
    return poly;
  }

  function rsEncode(data, ecLen) {
    const gen = rsGeneratorPoly(ecLen);
    const res = new Uint8Array(ecLen);
    for (let i = 0; i < data.length; i++) {
      const factor = data[i] ^ res[0];
      for (let j = 0; j < ecLen - 1; j++) res[j] = res[j + 1];
      res[ecLen - 1] = 0;
      for (let j = 0; j < ecLen; j++) {
        res[j] ^= gfMul(gen[j + 1], factor);
      }
    }
    return res;
  }

  // Version table for Level L (1..10): [totalDataCodewords, ecCodewordsPerBlock, numBlocks1, dataPerBlock1, numBlocks2, dataPerBlock2, alignCoords]
  const VERSIONS = [
    null,
    [19, 7, 1, 19, 0, 0, []],
    [34, 10, 1, 34, 0, 0, [6, 18]],
    [55, 15, 1, 55, 0, 0, [6, 22]],
    [80, 20, 1, 80, 0, 0, [6, 26]],
    [108, 26, 1, 108, 0, 0, [6, 30]],
    [136, 18, 2, 68, 0, 0, [6, 34]],
    [156, 20, 2, 78, 0, 0, [6, 22, 38]],
    [194, 24, 2, 97, 0, 0, [6, 24, 42]],
    [232, 30, 2, 116, 0, 0, [6, 26, 46]],
    [274, 18, 2, 68, 2, 69, [6, 28, 50]]
  ];

  function encodeMatrix(text) {
    const bytes = new TextEncoder().encode(text);
    let ver = 1;
    while (ver <= 10) {
      const cap = VERSIONS[ver][0] - (ver <= 9 ? 2 : 3);
      if (bytes.length <= cap) break;
      ver++;
    }
    if (ver > 10) return null;

    const [totalData, ecLen, nb1, db1, nb2, db2, align] = VERSIONS[ver];
    const bits = [];
    function pushBits(val, len) {
      for (let i = len - 1; i >= 0; i--) bits.push((val >>> i) & 1);
    }

    pushBits(0b0100, 4); // Byte mode
    pushBits(bytes.length, ver <= 9 ? 8 : 16);
    for (let i = 0; i < bytes.length; i++) pushBits(bytes[i], 8);

    const maxBits = totalData * 8;
    const term = Math.min(4, maxBits - bits.length);
    pushBits(0, term);
    while (bits.length % 8 !== 0) bits.push(0);

    const dataWords = new Uint8Array(totalData);
    for (let i = 0; i < bits.length / 8; i++) {
      let b = 0;
      for (let j = 0; j < 8; j++) b = (b << 1) | bits[i * 8 + j];
      dataWords[i] = b;
    }
    const pads = [0xEC, 0x11];
    for (let i = bits.length / 8, p = 0; i < totalData; i++, p ^= 1) {
      dataWords[i] = pads[p];
    }

    // Split into blocks & compute EC
    const dataBlocks = [];
    const ecBlocks = [];
    let offset = 0;
    for (let i = 0; i < nb1; i++) {
      const blk = dataWords.slice(offset, offset + db1);
      offset += db1;
      dataBlocks.push(blk);
      ecBlocks.push(rsEncode(blk, ecLen));
    }
    for (let i = 0; i < nb2; i++) {
      const blk = dataWords.slice(offset, offset + db2);
      offset += db2;
      dataBlocks.push(blk);
      ecBlocks.push(rsEncode(blk, ecLen));
    }

    const finalWords = [];
    const maxDataLen = Math.max(db1, db2);
    for (let i = 0; i < maxDataLen; i++) {
      for (let b = 0; b < dataBlocks.length; b++) {
        if (i < dataBlocks[b].length) finalWords.push(dataBlocks[b][i]);
      }
    }
    for (let i = 0; i < ecLen; i++) {
      for (let b = 0; b < ecBlocks.length; b++) {
        finalWords.push(ecBlocks[b][i]);
      }
    }

    const size = ver * 4 + 17;
    const mat = Array.from({ length: size }, () => new Int8Array(size));
    const isFunc = Array.from({ length: size }, () => new Uint8Array(size));

    function setFunc(r, c, val) {
      if (r >= 0 && r < size && c >= 0 && c < size) {
        mat[r][c] = val ? 1 : 0;
        isFunc[r][c] = 1;
      }
    }

    function drawFinder(r, c) {
      for (let dy = -1; dy <= 7; dy++) {
        for (let dx = -1; dx <= 7; dx++) {
          const inOuter = (dy >= 0 && dy <= 6 && (dx === 0 || dx === 6)) || (dx >= 0 && dx <= 6 && (dy === 0 || dy === 6));
          const inInner = dy >= 2 && dy <= 4 && dx >= 2 && dx <= 4;
          setFunc(r + dy, c + dx, inOuter || inInner);
        }
      }
    }

    drawFinder(0, 0);
    drawFinder(0, size - 7);
    drawFinder(size - 7, 0);

    for (let i = 8; i < size - 8; i++) {
      setFunc(6, i, i % 2 === 0);
      setFunc(i, 6, i % 2 === 0);
    }

    for (let i = 0; i < align.length; i++) {
      for (let j = 0; j < align.length; j++) {
        if ((i === 0 && j === 0) || (i === 0 && j === align.length - 1) || (i === align.length - 1 && j === 0)) continue;
        const ar = align[i], ac = align[j];
        for (let dy = -2; dy <= 2; dy++) {
          for (let dx = -2; dx <= 2; dx++) {
            setFunc(ar + dy, ac + dx, Math.max(Math.abs(dy), Math.abs(dx)) !== 1);
          }
        }
      }
    }

    // Reserve format info
    for (let i = 0; i < 9; i++) {
      if (i !== 6) {
        setFunc(8, i, 0);
        setFunc(i, 8, 0);
      }
    }
    for (let i = 0; i < 8; i++) {
      setFunc(8, size - 1 - i, 0);
      setFunc(size - 1 - i, 8, 0);
    }
    setFunc(size - 8, 8, 1);

    // Place data bits
    let bitIdx = 0;
    const totalBits = finalWords.length * 8;
    let upward = true;
    for (let right = size - 1; right >= 1; right -= 2) {
      if (right === 6) right = 5;
      for (let vert = 0; vert < size; vert++) {
        const r = upward ? size - 1 - vert : vert;
        for (let j = 0; j < 2; j++) {
          const c = right - j;
          if (!isFunc[r][c]) {
            let bit = 0;
            if (bitIdx < totalBits) {
              bit = (finalWords[bitIdx >>> 3] >>> (7 - (bitIdx & 7))) & 1;
              bitIdx++;
            }
            // Mask 0: (r + c) % 2 === 0
            if ((r + c) % 2 === 0) bit ^= 1;
            mat[r][c] = bit;
          }
        }
      }
      upward = !upward;
    }

    // Format info for Level L (01) and Mask 0 (000) -> 0x77C4
    const fmt = 0x77c4;
    const fmtBits = [];
    for (let i = 0; i < 15; i++) fmtBits.push((fmt >>> i) & 1);

    for (let i = 0; i <= 5; i++) mat[8][i] = fmtBits[i];
    mat[8][7] = fmtBits[6];
    mat[8][8] = fmtBits[7];
    mat[7][8] = fmtBits[8];
    for (let i = 9; i < 15; i++) mat[14 - i][8] = fmtBits[i];

    for (let i = 0; i < 8; i++) mat[8][size - 1 - i] = fmtBits[i];
    for (let i = 8; i < 15; i++) mat[size - 15 + i][8] = fmtBits[i];

    return mat;
  }

  function QRCode(el, opts) {
    if (typeof el === 'string') el = document.getElementById(el);
    if (!el) return;
    const text = (typeof opts === 'string') ? opts : (opts.text || '');
    const width = opts.width || 180;
    const height = opts.height || 180;
    const colorDark = opts.colorDark || '#0F2D59';
    const colorLight = opts.colorLight || '#FFFFFF';

    el.innerHTML = '';
    const mat = encodeMatrix(text);
    if (mat) {
      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      ctx.fillStyle = colorLight;
      ctx.fillRect(0, 0, width, height);

      const n = mat.length;
      const margin = 2;
      const cell = width / (n + margin * 2);
      ctx.fillStyle = colorDark;
      for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
          if (mat[r][c]) {
            ctx.fillRect(
              Math.floor((c + margin) * cell),
              Math.floor((r + margin) * cell),
              Math.ceil(cell),
              Math.ceil(cell)
            );
          }
        }
      }
      el.appendChild(canvas);
    } else {
      const img = document.createElement('img');
      img.width = width;
      img.height = height;
      img.alt = 'QR Code ASPIRASI BMN';
      img.src = 'https://api.qrserver.com/v1/create-qr-code/?size=' + width + 'x' + height + '&data=' + encodeURIComponent(text);
      el.appendChild(img);
    }
  }

  QRCode.CorrectLevel = { L: 1, M: 0, Q: 3, H: 2 };
  global.QRCode = QRCode;
})(window);
